package licensing

import (
	"crypto/sha256"
	"encoding/hex"
)

// DefaultServerURL is the license server used when client_config.json names none
// (release_key.py, generated by studio/tools/configure_release.py).
const DefaultServerURL = "https://license.scadabench.com"

// The accepted Ed25519 public keys, XOR-masked exactly as release_key.py stores them so
// they do not appear as a plain searchable hex string; they are public, not secret.
// configure_release.py must update this copy together with the Python and native ones.
var (
	keyMask    = mustHex("5d1fa7c3398e04b26af10c947e23d8a1")
	maskedKeys = []string{
		"1d13befc03e02574daee137734f229016c9b29de7aa60b0af8daa2a515ec395b",
		"643e9cd9c4e2f9e2a1369845b63a4894cad95c8a42cc033a756e9ca0a259f1a1",
	}
)

func mustHex(text string) []byte {
	data, err := hex.DecodeString(text)
	if err != nil {
		panic(err)
	}
	return data
}

func unmask(masked string) []byte {
	data := mustHex(masked)
	for index := range data {
		data[index] ^= keyMask[index%len(keyMask)]
	}
	return data
}

// KeyID is the short identifier a certificate carries as "kid": the first 8 hex digits of
// SHA-256 over the public key.
func KeyID(publicKey []byte) string {
	digest := sha256.Sum256(publicKey)
	return hex.EncodeToString(digest[:])[:8]
}

// PublicKeys returns {kid: public key} for every key this release accepts (a new map).
func PublicKeys() map[string][]byte {
	keys := map[string][]byte{}
	for _, masked := range maskedKeys {
		key := unmask(masked)
		keys[KeyID(key)] = key
	}
	return keys
}

// Configured reports whether this build has release keys and a default server.
func Configured() bool { return len(maskedKeys) > 0 && DefaultServerURL != "" }
